const body = $input.first().json.body || {};
const message = String(body.message || '').trim();
const customer_name = String(body.customer_name || 'Kunde').trim().slice(0, 100);
const business_name = String(body.business_name || 'Mukryan Demo').trim().slice(0, 100);
const email = String(body.email || '').trim().slice(0, 200);
const valid = message.length >= 10 && message.length <= 5000;

return [{json: {
  valid: valid,
  customer_name: customer_name,
  business_name: business_name,
  email: email,
  message: message,
  error: valid ? null : 'message must contain 10 to 5000 characters'
}}];

const response = $input.first().json;
const request = $('Validate Request').first().json;
const raw = response.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('') || '';
let answer = {};

try {
  answer = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim());
} catch (error) {
  answer = {category: 'other', priority: 'normal', summary: 'AI output requires review', suggested_reply: raw};
}

const categories = ['technical', 'pricing', 'appointment', 'complaint', 'other'];
const priorities = ['low', 'normal', 'high'];
const category = categories.includes(answer.category) ? answer.category : 'other';
const priority = priorities.includes(answer.priority) ? answer.priority : 'normal';
const suggested_reply = typeof answer.suggested_reply === 'string' ? answer.suggested_reply.slice(0, 2500) : '';

return [{json: {
  project: 'support_reply_ai',
  customer_name: request.customer_name,
  email: request.email,
  category: category,
  priority: priority,
  summary: typeof answer.summary === 'string' ? answer.summary : '',
  suggested_reply: suggested_reply,
  needs_review: true,
  note: 'Draft only. Check the answer before sending it to the customer.'
}}];

const data = $input.first().json;
return [{json: {
  project: 'support_reply_ai',
  status: 'bad_request',
  error: data.error
}}];
